// Military air defence radar. The Ministry of Defence operates air defence
// radar at Remote Radar Head sites, and MOD safeguarding of those sites is
// what most often decides a UK wind farm application. NONE of it is in the
// data above, and this tool did not retrieve any of it.
//
// The community sector file used as one of the two civil sources carries the
// literal line ";Mil Radars TBA" where military sites would go. That absence
// is the evidence: the open aviation data sets do not carry them.
//
// The site names below are recalled from web search summaries, not retrieved
// documents, and NO coordinates are asserted for them. They are listed so that
// a user assessing a real site knows which authority to approach, not so the
// tool can model them.
export const UK_MILITARY_RADAR_NOTE = {
  retrieved: false,
  basis: 'search summaries, not primary sources',
  sites: [
    { name: 'RRH Benbecula', radar: 'Lockheed Martin AN/TPS-77 (AMES Type 92)' },
    { name: 'RRH Buchan', radar: 'Lockheed Martin AN/TPS-77 (AMES Type 92)' },
    { name: 'RRH Saxa Vord', radar: 'reported re-established; type unconfirmed' },
    { name: 'RRH Staxton Wold', radar: 'Indra LTR-25 deployable air defence radar' },
    { name: 'RRH Portreath', radar: 'BAE Systems Type 102' },
    { name: 'RRH Brizlee Wood', radar: 'type not established' },
    { name: 'RRH Trimingham', radar: 'AN/TPS-77 reported dismantled 2023' },
  ],
  caution: 'Site list and radar types are unverified. Coordinates are deliberately absent. '
    + 'Consult the Defence Infrastructure Organisation for safeguarding positions.',
};

// MEASURED POSITIONAL UNCERTAINTY of a wind farm record, in metres.
//
// This is not a quoted figure. It is what two ground-truth comparisons give,
// and they are the only two available:
//
//   Kelmarsh    the record sits 1,140 m from the true centroid of the six-turbine
//               array, 695 m from the nearest turbine and 1,623 m from the
//               furthest. The array radius is 483 m, so the error is 2.4 times
//               the size of the thing being located.
//   Penmanshiel the record sits 1,121 m from a known turbine position, or
//               1,289 m against a second third-party value for the same turbine.
//
// Both are planning positions filed before the layout was fixed, which is why
// they are out by roughly the same amount at two unrelated sites. n = 2. Treat
// this as the scale of the error, not as a bound on it.
export const POSITION_UNCERTAINTY_M = 1100;

// The coordinates in the table above are written to five decimal places, which
// is about a metre. THAT IS PRECISION. The number above is accuracy. Anything
// that presents a wind farm position to the user must show both, or it invites
// the reader to believe the five decimal places.
export const STATED_PRECISION_M = 1.1;

const R_EARTH = 6371008.8;

// Great-circle distance in metres. The rest of the tool works in a local
// tangent plane; these datasets are the only part that spans the country.
export function greatCircleM(aLat, aLon, bLat, bLon) {
  const p1 = aLat * Math.PI / 180, p2 = bLat * Math.PI / 180;
  const dp = p2 - p1, dl = (bLon - aLon) * Math.PI / 180;
  const h = Math.sin(dp / 2) ** 2 + Math.cos(p1) * Math.cos(p2) * Math.sin(dl / 2) ** 2;
  return 2 * R_EARTH * Math.asin(Math.sqrt(h));
}

// Initial great-circle bearing, degrees clockwise from true north.
export function initialBearingDeg(aLat, aLon, bLat, bLon) {
  const p1 = aLat * Math.PI / 180, p2 = bLat * Math.PI / 180;
  const dl = (bLon - aLon) * Math.PI / 180;
  const y = Math.sin(dl) * Math.cos(p2);
  const x = Math.cos(p1) * Math.sin(p2) - Math.sin(p1) * Math.cos(p2) * Math.cos(dl);
  return (Math.atan2(y, x) * 180 / Math.PI + 360) % 360;
}

export function farmRecord(i) {
  const f = UK_WIND_FARMS[i];
  if (!f) return null;
  return {
    index: i, name: f[0], lat: f[1], lon: f[2], mw: f[3],
    status: f[4], offshore: f[5] === 1, repdRef: f[6],
    // Null, not zero, where the database has no figure. A farm with no
    // recorded turbine count is not a farm with no turbines, and code that
    // sums these must not treat the two the same.
    // 46 records carry no installed capacity at all, nearly all of them
    // single-turbine schemes. Zero is the table's way of saying not recorded,
    // and a panel that prints "0 MW" states something the database does not.
    mwKnown: f[3] > 0,
    turbines: f[7] || null,
    tipHeightM: f[8] || null,
    turbineMw: f[9] || null,
    // A floor on the positional uncertainty from how coarsely the grid
    // reference was written, which is a different thing from the measured
    // uncertainty below and is usually the smaller of the two.
    gridPrecisionM: f[10] || null,
    live: LIVE_STATUSES.includes(f[4]),
    uncertaintyM: POSITION_UNCERTAINTY_M,
  };
}

/** How to print a capacity that may not have been recorded. */
export function farmCapacityLabel(rec) {
  return rec.mwKnown ? `${rec.mw} MW` : 'capacity not recorded';
}

/**
 * What the table holds, counted rather than asserted, so the map can say how
 * much of what it draws is real and how much is an assumption.
 */
export function farmAttributeCoverage() {
  const live = liveFarmIndices();
  let withCount = 0, withHeight = 0, turbines = 0;
  for (const i of live) {
    const f = UK_WIND_FARMS[i];
    if (f[7]) { withCount += 1; turbines += f[7]; }
    if (f[8]) withHeight += 1;
  }
  return { live: live.length, withCount, withHeight, turbines };
}

// Indices of the farms that exist or are expected to. Everything else in the
// table is a project that was refused, withdrawn, abandoned, expired or
// superseded, and counting those as wind farms overstates the fleet by a
// factor of three.
export function liveFarmIndices() {
  const out = [];
  for (let i = 0; i < UK_WIND_FARMS.length; i += 1) {
    if (LIVE_STATUSES.includes(UK_WIND_FARMS[i][4])) out.push(i);
  }
  return out;
}

export function radarRecord(i) {
  const r = UK_RADAR_SITES[i];
  if (!r) return null;
  return {
    index: i, name: r[0], role: r[1], lat: r[2], lon: r[3],
    sources: r[4].split(','), disagreementM: r[5] || 0,
  };
}

// Nearest radar site to a point, optionally restricted by role.
export function nearestRadar(lat, lon, role = null) {
  let best = null;
  for (let i = 0; i < UK_RADAR_SITES.length; i += 1) {
    const r = UK_RADAR_SITES[i];
    if (role && r[1] !== role) continue;
    const d = greatCircleM(lat, lon, r[2], r[3]);
    if (!best || d < best.distanceM) {
      best = { ...radarRecord(i), distanceM: d, bearingDeg: initialBearingDeg(r[2], r[3], lat, lon) };
    }
  }
  return best;
}

// Turn a real farm/radar pairing into the scenario geometry this tool uses:
// the radar sits at the origin and the farm centre is placed on the true
// bearing from it, at the true great-circle range.
export function pairingGeometry(farmIndex, radarIndex = null) {
  const farm = farmRecord(farmIndex);
  if (!farm) return null;
  const radar = radarIndex == null
    ? nearestRadar(farm.lat, farm.lon)
    : { ...radarRecord(radarIndex) };
  if (radar.distanceM == null) {
    radar.distanceM = greatCircleM(radar.lat, radar.lon, farm.lat, farm.lon);
    radar.bearingDeg = initialBearingDeg(radar.lat, radar.lon, farm.lat, farm.lon);
  }
  const br = radar.bearingDeg * Math.PI / 180;
  return {
    farm,
    radar,
    rangeM: radar.distanceM,
    bearingDeg: radar.bearingDeg,
    east: radar.distanceM * Math.sin(br),
    north: radar.distanceM * Math.cos(br),
    // Positions this far apart are NOT flat. Over 100 km the tangent-plane
    // approximation the scene uses starts to matter, so say so rather than
    // hide it.
    tangentPlaneWarning: radar.distanceM > 100000,
    // How much of this range is measurement error. Above about a fifth the
    // geometry is no longer telling you anything useful about this site.
    uncertaintyM: POSITION_UNCERTAINTY_M,
    uncertaintyFraction: POSITION_UNCERTAINTY_M / Math.max(radar.distanceM, 1),
  };
}
